use crate::invariant::{Enforced, Status};
use dacc_core::NonEmptyStr;

crate::invariant!(
    id: NonEmptyStr::new("INV-PREMISE-002"),
    status: Status::Enforced(Enforced::Adversarial { bypass: NonEmptyStr::new("An unkeyed digest of something read reaching a plan's JSON or state — the premise as it was, or a field somebody adds beside it. Or a premise accepted bare, which is the same digest through the other door. Or a write that carries a secret and does not say so, which is answered with what the far end read back: the provider marks it and the engine checks the mark, so this needs both of them to be wrong at once. Or a private process whose output comes home: its status answers for it and everything it printed leaves as a sealed digest, which is the half that was missing while only its input was withheld. Not covered, on purpose: a machine holding its own seal can test guesses against its own premise, which describes its own disk."), tests: &[crate::anchor::a_rotated_secret_leaves_no_unkeyed_digest_of_the_old_one_in_the_plan, crate::anchor::a_premise_that_arrives_without_its_seal_is_refused_before_anything_is_done, crate::anchor::a_write_carrying_a_secret_without_a_seal_is_refused_before_anything, crate::anchor::a_premise_sealed_for_another_machine_does_not_hold, crate::anchor::a_private_process_answers_with_a_seal_and_never_with_what_it_said] }),
    statement: NonEmptyStr::new("A premise leaves the planner only sealed for the machine it describes, a write that carries a secret says so, a private process answers with a seal, and an executor refuses any of them that arrives without one."),
    rationale: r#"A premise is a digest of what was read, and what was read is sometimes a secret. Unsealed, a plan's JSON carried an unkeyed digest of a credential on disk, and a dictionary defeats an unkeyed digest of a short one in seconds — found by a test before any secret store was real. The planner seals each digest under a key derived from the state file's and the machine's name, the engine puts that seal on the batch as it leaves and never in the plan, and the executor seals what it reads again and compares, refusing a premise that came bare. See 0041.

Protocol 5 extends it to what is written. A write carrying a secret is answered with a sealed digest rather than with what the far end read back, because for a file whose contents are a password what was read back is the password. So such a write says it carries one: the executor refuses a batch carrying a marked write that arrived without a seal, having nothing to seal the answer with, and the engine refuses before sending a change whose secret is carried by an operation that does not say so. The provider marks it and the engine checks the mark, so one forgetful provider is not enough to send a secret bare.

The same holds for what a private process says. Its status is the answer, and everything it printed leaves as one digest sealed for the machine: a program handed a credential on its input usually says something about it, and a failure that quoted it would put it in the most reliably logged place there is."#,
    enforced_by: &[crate::anchor::executor_perform, crate::anchor::inv_premise_002_3, crate::anchor::planner_change_for, crate::anchor::run_apply],
    tests: &[crate::anchor::a_rotated_secret_leaves_no_unkeyed_digest_of_the_old_one_in_the_plan, crate::anchor::a_premise_that_arrives_without_its_seal_is_refused_before_anything_is_done, crate::anchor::a_write_carrying_a_secret_without_a_seal_is_refused_before_anything, crate::anchor::a_secret_carried_by_a_write_that_is_not_marked_secret_is_refused, crate::anchor::a_write_that_carries_a_secret_says_so, crate::anchor::a_private_process_answers_with_a_seal_and_never_with_what_it_said, crate::anchor::a_private_process_that_fails_does_not_quote_what_it_said, crate::anchor::a_premise_sealed_for_another_machine_does_not_hold, crate::anchor::a_seal_belongs_to_one_machine_under_one_state_file, crate::anchor::a_sealed_observation_answers_with_a_seal_and_never_the_contents],
);
